// Create a function
async function updateDataGrid() {
    // Get all items from the data-source using its id
    const items = await tf.getDataSource('72ks2ts6a1p4');

    // Apply a filter based on data in the form
    const filteredItems = items.filter(i => i?.TECHNICIAN === data.technicianName.TECHNICIAN);

    // IMPORTANT: Use a "Map" to rename the columns from the data source to match the 
    // names of field names used in the data-grid
    const gridItems = filteredItems.map(i => {
        return {
            techNumber: parseInt(i?.['TECH #']?.substring(1) || '0', 10), // Remove the "T" and parse the number
            techLevel: parseInt(i?.LEVEL || '0', 10),
            payRate: parseInt(i?.PAY || '0',10),
            branch: i?.LOCATION || ''
        };
    });

    // Set the value of the data-grid component programmatically
    instance.root.getComponent('techNumberLevelBranch').setValue(gridItems);
}

// Invoke the function
updateDataGrid();
